private TaintedDataSymbolMap<T> GetFromMap<T>(
    SinkKind sinkKind,
    ImmutableDictionary<SinkKind, Lazy<TaintedDataSymbolMap<T>>> map
)
    where T : ITaintedDataInfo
{
    if (map.TryGetValue(sinkKind, out var lazySourceSymbolMap))
    {
        return lazySourceSymbolMap.Value;
